'use client';
import { type ReactNode, useRef, useState } from 'react';
import { motion, useInView, type Variant, type Transition, type UseInViewOptions } from 'motion/react';

export type InViewProps = {
  children: ReactNode;
  variants?: {
    hidden: Variant;
    visible: Variant;
  };
  transition?: Transition;
  viewOptions?: UseInViewOptions;
  as?: React.ElementType;
  once?: boolean
};

const defaultVariants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

export function InView({
  children,
  variants = defaultVariants,
  transition,
  viewOptions,
  as = 'div',
  once
}: InViewProps) {
  const ref = useRef(null);
  const isInView = useInView(ref, viewOptions);

  const [isViewed, setIsViewed] = useState(false)

  const MotionComponent = motion[as as keyof typeof motion] as typeof as;

  return (
    <MotionComponent
      ref={ref}
      initial='hidden'
      onAnimationComplete={() => {
        if (once) setIsViewed(true)
      }}
      animate={(isInView || isViewed) ? "visible" : "hidden"}

      variants={variants}
      transition={transition}
    >
      {children}
    </MotionComponent>
  );
}

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"
import { InView } from "@/components/primitives/in-view"
import { SectionHead, SectionShell } from "@/components/primitives/handcraft"
import { cn } from "@/lib/utils"

// The layer components — head, task rows (repeat like fillings), progress rail, base.
import { BoardTop } from "./layers/BoardTop"
import { BoardTask } from "./layers/BoardTask"
import { BoardProgress } from "./layers/BoardProgress"
import { BoardBase } from "./layers/BoardBase"

// ═══ JOB         Get a new user to first value, one honest row at a time.
// ═══ EMOTION     A checklist that wants to be finished — quiet momentum.
// ═══ SIGNATURE   The base lights up: tick the last filling and the CTA
//                 snaps from muted to ink with a spring, while the progress
//                 rail fills. Rows are components — add or remove freely.

export type OnboardTaskDef = { label: string; hint?: string }

export type StackOnboardProps = {
  eyebrow?: string
  title?: React.ReactNode
  subtitle?: React.ReactNode
  heading?: string
  headingSub?: string
  tasks?: OnboardTaskDef[]
  cta?: string
  caption?: string
  tone?: "paper" | "ink"
  className?: string
}

export function StackOnboard({
  eyebrow = "STACK · ONBOARDING",
  title = "A checklist built from layers.",
  subtitle = "Head band, task rows, progress rail and action base are separate components — rows repeat like fillings. Tick them all and the base CTA snaps awake.",
  heading = "Welcome in",
  headingSub = "Four steps and the studio is yours.",
  tasks = [
    { label: "Set your opening hours", hint: "the board books around them" },
    { label: "Add your first client", hint: "or import a CSV" },
    { label: "Name your chairs", hint: "03 is luckier than 4" },
    { label: "Send one booking link", hint: "copy it anywhere" },
  ],
  cta = "Enter the studio",
  caption = "FOUR LAYER COMPONENTS · REPEATABLE FILLINGS",
  tone = "paper",
  className,
}: StackOnboardProps) {
  const ink = tone === "ink"
  const reduce = useReducedMotion()
  const [done, setDone] = React.useState<boolean[]>(() => tasks.map(() => false))
  const count = done.filter(Boolean).length
  const ready = count === tasks.length && tasks.length > 0

  const toggle = (i: number) =>
    setDone((cur) => cur.map((v, x) => (x === i ? !v : v)))

  return (
    <SectionShell tone={tone} width={920} rule="bottom" className={className}>
      <InView
        once
        variants={{ hidden: { opacity: 0, y: 14 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
      >
        <SectionHead eyebrow={eyebrow} title={title} subtitle={subtitle} tone={tone} />
      </InView>

      <InView
        once
        variants={{ hidden: { opacity: 0, y: 24 }, visible: { opacity: 1, y: 0 } }}
        transition={{ duration: 0.9, ease: [0.16, 1, 0.3, 1], delay: 0.1 }}
      >
        <figure className="mt-10">
          <div className="mx-auto max-w-[460px]">
            <motion.div
              whileHover={reduce ? undefined : { y: -3 }}
              transition={{ type: "spring", stiffness: 260, damping: 24 }}
              className={cn(
                "overflow-hidden rounded-[16px] border bg-card shadow-[0_24px_52px_-30px_hsl(var(--foreground)/0.45)]",
                ink ? "border-background/15" : "border-border",
              )}
            >
              <BoardTop title={heading} subtitle={headingSub} done={count} total={tasks.length} />

              {/* task rows — the repeatable fillings */}
              <div role="group" aria-label="Onboarding steps">
                {tasks.map((task, i) => (
                  <motion.div
                    key={task.label}
                    initial={reduce ? { opacity: 0 } : { opacity: 0, x: -14 }}
                    whileInView={{ opacity: 1, x: 0 }}
                    viewport={{ once: true }}
                    transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1], delay: 0.2 + i * 0.07 }}
                  >
                    <BoardTask
                      label={task.label}
                      hint={task.hint}
                      done={done[i]}
                      onToggle={() => toggle(i)}
                    />
                  </motion.div>
                ))}
              </div>

              <motion.div
                initial={reduce ? { opacity: 0 } : { opacity: 0, y: 12 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true }}
                transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1], delay: 0.55 }}
              >
                <BoardProgress done={count} total={tasks.length} />
                <BoardBase ready={ready} cta={cta} onCta={() => {}} onSkip={() => {}} />
              </motion.div>
            </motion.div>
          </div>

          {caption && (
            <figcaption
              className={cn(
                "mx-auto mt-8 flex max-w-[460px] items-center justify-between border-t pt-3 font-mono text-[10px] font-bold uppercase tracking-[0.3em]",
                ink ? "border-background/15 text-background/55" : "border-border text-muted-foreground",
              )}
            >
              <span>{caption}</span>
              <span aria-hidden className="tabular-nums">{String(count).padStart(2, "0")} / {String(tasks.length).padStart(2, "0")}</span>
            </figcaption>
          )}
        </figure>
      </InView>
    </SectionShell>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── BOARD BASE — the bottom bun. Skip / continue, lights up when done. ──────

export type BoardBaseProps = {
  cta?: string
  onCta?: () => void
  onSkip?: () => void
  ready?: boolean
  className?: string
}

export function BoardBase({ cta = "Enter the studio", onCta, onSkip, ready, className }: BoardBaseProps) {
  return (
    <div className={cn("flex items-center gap-3 rounded-b-[14px] border-t border-app-line/70 bg-muted/30 px-5 py-3.5", className)}>
      <button
        type="button"
        onClick={onSkip}
        className="font-mono text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground transition-colors hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
      >
        Skip for now
      </button>
      <button
        type="button"
        onClick={onCta}
        aria-disabled={!ready}
        className={cn(
          "ml-auto h-9 rounded-full px-5 text-[11px] font-black uppercase tracking-[0.14em] transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
          ready
            ? "bg-foreground text-background hover:-translate-y-0.5"
            : "cursor-not-allowed bg-muted text-muted-foreground",
        )}
      >
        {cta}
      </button>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── BOARD PROGRESS — the rail between the fillings and the base. ────────────

export type BoardProgressProps = {
  done?: number
  total?: number
  className?: string
}

export function BoardProgress({ done = 0, total = 4, className }: BoardProgressProps) {
  const pct = total > 0 ? Math.round((done / total) * 100) : 0
  return (
    <div className={cn("border-t border-app-line/70 px-5 py-3", className)}>
      <div className="flex items-center justify-between font-mono text-[9px] font-bold uppercase tracking-[0.2em] text-muted-foreground">
        <span>Progress</span>
        <span className="tabular-nums">{pct}%</span>
      </div>
      <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-muted" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={pct} aria-label="Onboarding progress">
        <div className="h-full rounded-full bg-primary transition-[width] duration-500 ease-out" style={{ width: `${pct}%` }} />
      </div>
    </div>
  )
}

import * as React from "react"
import { Check } from "lucide-react"
import { cn } from "@/lib/utils"

// ── BOARD TASK — one filling. Render one row per step; repeat freely. ───────

export type BoardTaskProps = {
  label: string
  hint?: string
  done?: boolean
  onToggle?: () => void
  className?: string
}

export function BoardTask({ label, hint, done, onToggle, className }: BoardTaskProps) {
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={!!done}
      onClick={onToggle}
      className={cn(
        "flex w-full items-center gap-3 border-b border-app-line/50 px-5 py-3.5 text-left transition-colors last:border-b-0 hover:bg-muted/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
        className,
      )}
    >
      <span
        aria-hidden
        className={cn(
          "flex size-5 shrink-0 items-center justify-center rounded-md border transition-all",
          done ? "border-primary bg-primary text-primary-foreground" : "border-border bg-background",
        )}
      >
        {done && <Check className="size-3" strokeWidth={3.5} />}
      </span>
      <span className="min-w-0">
        <span className={cn("block truncate text-[13px] font-bold", done && "text-muted-foreground line-through decoration-border")}>{label}</span>
        {hint && <span className="block truncate text-[11px] font-medium text-muted-foreground">{hint}</span>}
      </span>
    </button>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

// ── BOARD TOP — the upper bun. Greets, and counts what's left. ──────────────

export type BoardTopProps = {
  title?: string
  subtitle?: string
  done?: number
  total?: number
  className?: string
}

export function BoardTop({ title = "Welcome in", subtitle = "Four steps and the studio is yours.", done = 0, total = 4, className }: BoardTopProps) {
  return (
    <div className={cn("flex items-center justify-between rounded-t-[14px] border-b border-app-line/70 bg-muted/40 px-5 py-4", className)}>
      <div>
        <p className="font-display text-[15px] font-black tracking-tight">{title}</p>
        <p className="mt-0.5 text-[12px] font-medium text-muted-foreground">{subtitle}</p>
      </div>
      <span className="rounded-full border bg-background px-2.5 py-1 font-mono text-[10px] font-black tabular-nums" aria-live="polite">
        {done}/{total}
      </span>
    </div>
  )
}
